import requests
from requests.models import PreparedRequest

class FileWrapper:
    def __init__(self, content):
        self._content = content
    def __getattr__(self, name):
        if name == "read":
            return lambda: self._content
        raise AttributeError(name)

def test_getattr_wrapper():
    pr = PreparedRequest()
    files = {"file": FileWrapper(b"hello world")}
    # This should not raise an error and should correctly encode the file
    try:
        body, content_type = pr._encode_files(files, None)
        print("Success!")
        assert b"hello world" in body
    except Exception as e:
        print(f"Failed: {e}")
        raise e

