from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from typing import Optional
import pytest

app = FastAPI()

@app.post("/test")
async def test_endpoint(name: Optional[str] = Form(None)):
    return {"name": name}

client = TestClient(app)

def test_empty_string_as_none():
    # When sending an empty string for an optional field with None default,
    # it should be treated as None (or the default value), not as an empty string
    # that might fail validation if the type was different, but here it's str.
    # Actually, the issue says "validation would choke on that empty string".
    # Let's try a type that doesn't allow empty strings if possible, or just check the value.

    # If name is Optional[str] = Form(None), and we send name="", 
    # _get_multidict_value should return None.
    # Then it's NOT added to values in the first loop of _extract_form_body.
    # Then in the second loop, it IS added because it's in received_body.
    # So the final value becomes "".

    response = client.post("/test", data={"name": ""})
    assert response.status_code == 200
    assert response.json() == {"name": None}

def test_non_empty_string():
    response = client.post("/test", data={"name": "foo"})
    assert response.status_code == 200
    assert response.json() == {"name": "foo"}

def test_missing_field():
    response = client.post("/test", data={})
    assert response.status_code == 200
    assert response.json() == {"name": None}

if __name__ == "__main__":
    try:
        test_empty_string_as_none()
        print("test_empty_string_as_none passed")
    except AssertionError as e:
        print(f"test_empty_string_as_none failed: {e}")

    try:
        test_non_empty_string()
        print("test_non_empty_string passed")
    except AssertionError as e:
        print(f"test_non_empty_string failed: {e}")

    try:
        test_missing_field()
        print("test_missing_field passed")
    except AssertionError as e:
        print(f"test_missing_field failed: {e}")
